import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { MaksterEngineeringCompiler } from '../../../packages/engineering-engine/src/index.js';
import { buildProductionPack } from '../../../packages/production-pack/src/index.js';
import { buildReworkPack, createReceipt, createSupplierOrder, receivingSummary, receivingSummaryCsv, reworkCsv, supplierOrderCsv, updateSupplierOrderStatus } from '../../../packages/supplier-operations/src/index.js';
const out = process.argv[2] ?? 'engineering-output/supplier-receiving-demo';
await mkdir(out, { recursive: true });
const p = JSON.parse(await readFile(join(process.cwd(), 'packages/project-model/examples/wardrobe.blum.v1.json'), 'utf8'));
const engineering = new MaksterEngineeringCompiler().compile(p);
const pack = buildProductionPack({ project: p, engineering, route: 'outsource', outsourcePreset: 'cutting_edging', packId: 'demo-pack-1.1', generatedAt: '2026-09-03T12:00:00Z' });
let order = createSupplierOrder({ pack, supplier: { id: 'supplier-demo', name: 'Demo Cut & Edge Partner', email: 'production@example.test' }, currency: 'EUR', quotedPrice: 428, promisedAt: '2026-09-08T12:00:00Z', supplierReference: 'SUP-2026-778', orderId: 'demo-supplier-order', createdAt: '2026-09-03T12:01:00Z' });
order = updateSupplierOrderStatus(order, { status: 'sent', at: '2026-09-03T12:05:00Z' });
order = updateSupplierOrderStatus(order, { status: 'accepted', at: '2026-09-03T13:00:00Z' });
order = updateSupplierOrderStatus(order, { status: 'in_production', at: '2026-09-04T08:00:00Z' });
order = updateSupplierOrderStatus(order, { status: 'ready', at: '2026-09-08T10:00:00Z' });
const damaged = order.lines.find(l => l.quantity === 2);
const missing = order.lines.find(l => l.quantity === 1 && l.partId !== damaged.partId);
const good = order.lines.filter(l => l.partId !== damaged.partId && l.partId !== missing.partId).map(l => ({ partId: l.partId, quantity: l.quantity, disposition: 'accepted' }));
const receipt = createReceipt({ order, receivedBy: 'Vyacheslav', receivedAt: '2026-09-08T14:00:00Z', receiptId: 'demo-receipt-1', lines: [...good, { partId: damaged.partId, quantity: 1, disposition: 'accepted' }, { partId: damaged.partId, quantity: 1, disposition: 'damaged', note: 'Chipped edge' }, { partId: missing.partId, quantity: 1, disposition: 'missing' }] });
const summary = receivingSummary(order, [receipt]);
const rework = buildReworkPack(order, [receipt], '2026-09-08T14:05:00Z');
await writeFile(join(out, '01-supplier-order.json'), JSON.stringify(order, null, 2));
await writeFile(join(out, '02-supplier-order-lines.csv'), supplierOrderCsv(order));
await writeFile(join(out, '03-receipt.json'), JSON.stringify(receipt, null, 2));
await writeFile(join(out, '04-receiving-summary.json'), JSON.stringify(summary, null, 2));
await writeFile(join(out, '05-receiving-summary.csv'), receivingSummaryCsv(summary));
await writeFile(join(out, '06-rework-pack.json'), JSON.stringify(rework, null, 2));
await writeFile(join(out, '07-rework-pack.csv'), reworkCsv(rework));
console.log(JSON.stringify({ orderStatus: order.status, receivedStatus: summary.status, totalOrdered: summary.totalOrdered, totalAccepted: summary.totalAccepted, totalOutstanding: summary.totalOutstanding, reworkLines: rework.lines.length, reworkQuantity: rework.lines.reduce((s, l) => s + l.quantity, 0) }, null, 2));
